function literalsOf (clauses) {
  const out = []
  const seen = new Set()
  for (const clause of (clauses || [])) {
    const re = /`([^`]*)`/g
    let m
    while ((m = re.exec(String(clause)))) {
      const s = m[1]
      if (s.length >= 3 && !seen.has(s)) { seen.add(s); out.push(s) }
    }
  }
  return out
}

export function settledCoverage ({ clauses, proofRunClauses, runLines }) {
  return (clauses || []).map((_, i) => {
    const tag = 'M' + (i + 1)
    const citing = []
    ;(proofRunClauses || []).forEach((cites, k) => { if ((cites || []).includes(tag)) citing.push(k) })
    if (!citing.length) return null
    let allGreen = true
    for (const k of citing) {
      const r = (runLines || [])[k]
      if (!r || r.exit !== 0) { allGreen = false; break }
    }
    return allGreen ? 1 : 0
  })
}

export function observedFacts ({ clauses, hasExam, examExit, proofRuns, proofRunClauses, runLines, capBytes }) {
  const literals = literalsOf(clauses)
  const out = []
  if (hasExam) out.push({ kind: 'exam', exit: examExit })
  ;(proofRuns || []).forEach((cmd, k) => {
    const cites = (proofRunClauses || [])[k] || []
    const matchesLiteral = literals.some((lit) => String(cmd).includes(lit))
    if (cites.length || matchesLiteral) {
      const r = (runLines || [])[k] || {}
      out.push({ kind: 'run:line', cmd, exit: r.exit, cites })
    }
  })
  while (JSON.stringify(out).length > capBytes && out.length) out.pop()
  return out
}
