import fs from 'node:fs'

export function auditRows (rows, { state, bound } = {}) {
  const missing = []
  if (state !== 'done') return { kind: 'run:audit', state, missing }

  const landedTasks = []
  const verified = new Set()
  const seenLanding = new Set()
  for (const row of rows) {
    if (row.kind === 'landing') {
      if (!seenLanding.has(row.task)) { landedTasks.push(row.task); seenLanding.add(row.task) }
    } else if (row.kind === 'fold:verify') {
      verified.add(row.task)
    }
  }
  for (const task of landedTasks) {
    if (!verified.has(task)) missing.push(`fold:verify task ${task}`)
  }

  if (bound) {
    const closeOk = (what) => rows.some(r => r.kind === 'board:close' && r.what === what && Number.isInteger(r.code) && r.code >= 200 && r.code <= 299)
    for (const task of landedTasks) {
      if (!closeOk(`task ${task}`)) missing.push(`board:close task ${task}`)
    }
    if (!closeOk('run')) missing.push('board:close run')
    const leftOk = rows.some(r => r.kind === 'board:leave' && r.rc === 0)
    if (!leftOk) missing.push('board:leave')
  }

  return { kind: 'run:audit', state, missing }
}

function main (argv) {
  const [file, state, ...rest] = argv
  const bound = rest.includes('--bound')
  let rows = []
  try {
    const text = fs.readFileSync(file, 'utf8')
    rows = text.split('\n').filter(Boolean).map(line => {
      try { return JSON.parse(line) } catch { return null }
    }).filter(Boolean)
  } catch {
    rows = []
  }
  const result = auditRows(rows, { state, bound })
  process.stdout.write(JSON.stringify(result) + '\n')
  return 0
}

const invokedDirectly = process.argv[1] && process.argv[1].endsWith('scratch_audit.mjs')
if (invokedDirectly) {
  process.exitCode = main(process.argv.slice(2))
}
